1	/****************************************************************************
2	 * gpio_key_template.c
3	 *
4	 * GPIO 按键驱动模板 - 龙芯 2K300 NuttX 平台
5	 *
6	 * Hummingbird 2K300 板按键引脚：
7	 *   - KEY1: GPIO87（按下为低电平）
8	 *   - KEY2: GPIO86（按下为低电平）
9	 *
10	 * 使用方法：
11	 *   修改 KEY_PIN 选择要检测的按键
12	 *
13	 * 编译条件：
14	 *   CONFIG_GPIO=y
15	 *   CONFIG_IOEXPANDER=y
16	 ****************************************************************************/
17	
18	/****************************************************************************
19	 * Included Files
20	 ****************************************************************************/
21	
22	#include <nuttx/config.h>
23	#include <sys/ioctl.h>
24	#include <stdio.h>
25	#include <fcntl.h>
26	#include <unistd.h>
27	#include <stdint.h>
28	#include <nuttx/ioexpander/gpio.h>
29	
30	/****************************************************************************
31	 * Pre-processor Definitions
32	 ****************************************************************************/
33	
34	/* Hummingbird 2K300 板按键定义 */
35	
36	#define KEY1_PIN        87
37	#define KEY2_PIN        86
38	
39	/* 当前使用的按键（修改此值切换按键） */
40	
41	#define KEY_PIN         KEY1_PIN
42	#define KEY_ACTIVE_LOW  1                  /* 按下为低电平 */
43	#define DEBOUNCE_MS     20                 /* 消抖时间 */
44	
45	/* pinctrl 设置函数（需在板级代码中实现） */
46	
47	extern int pinctrl_set_gpio_function(int pin);
48	
49	/****************************************************************************
50	 * Private Data
51	 ****************************************************************************/
52	
53	static volatile int g_key_pressed = 0;
54	
55	/****************************************************************************
56	 * Private Functions
57	 ****************************************************************************/
58	
59	/****************************************************************************
60	 * Name: key_interrupt
61	 *
62	 * Description: GPIO 中断回调函数
63	 *
64	 ****************************************************************************/
65	
66	static int key_interrupt(int irq, void *context, void *arg)
67	{
68	  g_key_pressed = 1;
69	  return OK;
70	}
71	
72	/****************************************************************************
73	 * Name: key_read_debounced
74	 *
75	 * Description: 带消抖的按键读取
76	 *
77	 * 返回值: 1=确认按下, 0=未按下, -1=抖动中
78	 *
79	 ****************************************************************************/
80	
81	static int key_read_debounced(int fd)
82	{
83	  int val1, val2;
84	
85	  ioctl(fd, GPIOC_READ, &val1);
86	  up_mdelay(DEBOUNCE_MS);
87	  ioctl(fd, GPIOC_READ, &val2);
88	
89	  if (val1 != val2)
90	    {
91	      return -1;  /* 抖动 */
92	    }
93	
94	#if KEY_ACTIVE_LOW
95	  return (val1 == 0) ? 1 : 0;
96	#else
97	  return (val1 != 0) ? 1 : 0;
98	#endif
99	}
