105	/****************************************************************************
106	 * Name: gpio_key_poll_demo
107	 *
108	 * Description: 轮询方式读取按键
109	 *
110	 ****************************************************************************/
111	
112	int gpio_key_poll_demo(void)
113	{
114	  int fd;
115	  int ret;
116	
117	  printf("[KEY] GPIO Key Poll Demo on pin %d\n", KEY_PIN);
118	
119	  /* 设置引脚为 GPIO 模式 */
120	
121	  ret = pinctrl_set_gpio_function(KEY_PIN);
122	  if (ret < 0)
123	    {
124	      printf("[KEY] ERROR: pinctrl pin %d: %d\n", KEY_PIN, ret);
125	      return ret;
126	    }
127	
128	  /* 打开 GPIO 设备 */
129	
130	  char gpio_path[32];
131	  snprintf(gpio_path, sizeof(gpio_path), "/dev/gpio%d", KEY_PIN);
132	  fd = open(gpio_path, O_RDWR);
133	  if (fd < 0)
134	    {
135	      printf("[KEY] ERROR: open %s: %d\n", gpio_path, errno);
136	      return -errno;
137	    }
138	
139	  /* 设置为输入模式 */
140	
141	  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);
142	  if (ret < 0)
143	    {
144	      printf("[KEY] ERROR: set input: %d\n", errno);
145	      close(fd);
146	      return -errno;
147	    }
148	
149	  /* 轮询读取 */
150	
151	  printf("[KEY] Polling for key press (press any key 5 times)...\n");
152	
153	  int count = 0;
154	  while (count < 5)
155	    {
156	      int pressed = key_read_debounced(fd);
157	      if (pressed == 1)
158	        {
159	          count++;
160	          printf("[KEY] Key pressed! (%d/5)\n", count);
161	          /* 等待释放 */
162	          int val;
163	          do
164	            {
165	              ioctl(fd, GPIOC_READ, &val);
166	              up_mdelay(10);
167	            }
168	          while (
169	#if KEY_ACTIVE_LOW
170	            val == 0
171	#else
172	            val != 0
173	#endif
174	          );
175	        }
176	      up_mdelay(10);
177	    }
178	
179	  close(fd);
180	  printf("[KEY] Done.\n");
181	  return 0;
182	}
