184	/****************************************************************************
185	 * Name: gpio_key_irq_demo
186	 *
187	 * Description: 中断方式读取按键
188	 *
189	 ****************************************************************************/
190	
191	int gpio_key_irq_demo(void)
192	{
193	  int fd;
194	  int ret;
195	
196	  printf("[KEY] GPIO Key IRQ Demo on pin %d (IRQ %d)\n", KEY_PIN, KEY_IRQ);
197	
198	  /* 设置引脚为 GPIO 模式 */
199	
200	  ret = pinctrl_set_gpio_function(KEY_PIN);
201	  if (ret < 0)
202	    {
203	      printf("[KEY] ERROR: pinctrl pin %d: %d\n", KEY_PIN, ret);
204	      return ret;
205	    }
206	
207	  /* 打开 GPIO 设备 */
208	
209	  char gpio_path[32];
210	  snprintf(gpio_path, sizeof(gpio_path), "/dev/gpio%d", KEY_PIN);
211	  fd = open(gpio_path, O_RDWR);
212	  if (fd < 0)
213	    {
214	      printf("[KEY] ERROR: open %s: %d\n", gpio_path, errno);
215	      return -errno;
216	    }
217	
218	  /* 设置为输入模式 */
219	
220	  ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_INPUT_PIN);
221	
222	  /* 注册中断 */
223	
224	  ret = irq_attach(KEY_IRQ, key_interrupt, NULL);
225	  if (ret < 0)
226	    {
227	      printf("[KEY] ERROR: irq_attach: %d\n", ret);
228	      close(fd);
229	      return ret;
230	    }
231	
232	  up_enable_irq(KEY_IRQ);
233	
234	  /* 等待中断 */
235	
236	  printf("[KEY] Waiting for key interrupt...\n");
237	
238	  int count = 0;
239	  while (count < 5)
240	    {
241	      if (g_key_pressed)
242	        {
243	          g_key_pressed = 0;
244	          count++;
245	          printf("[KEY] Key interrupt! (%d/5)\n", count);
246	          up_mdelay(DEBOUNCE_MS);  /* 消抖 */
247	        }
248	      up_mdelay(10);
249	    }
250	
251	  up_disable_irq(KEY_IRQ);
252	  close(fd);
253	
254	  printf("[KEY] Done.\n");
255	  return 0;
256	}
