57	 * Public Functions
58	 ****************************************************************************/
59	
60	int gpio_led_demo(void)
61	{
62	  int fd;
63	  int ret;
64	  int state = 0;
65	
66	  printf("[LED] GPIO LED Demo on pin %d\n", LED_PIN);
67	
68	  /* Step 1: 设置引脚为 GPIO 模式 */
69	
70	  ret = pinctrl_set_gpio_function(LED_PIN);
71	  if (ret < 0)
72	    {
73	      printf("[LED] ERROR: pinctrl pin %d: %d\n", LED_PIN, ret);
74	      return ret;
75	    }
76	
77	  /* Step 2: 打开 GPIO 设备 */
78	
79	  char gpio_path[32];
80	  snprintf(gpio_path, sizeof(gpio_path), "/dev/gpio%d", LED_PIN);
81	  fd = open(gpio_path, O_RDWR);
82	  if (fd < 0)
83	    {
84	      printf("[LED] ERROR: open %s: %d\n", LED_GPIO_PATH, errno);
85	      return -errno;
86	    }
87	
88	  /* Step 3: 设置为输出模式 */
89	
90	  ret = ioctl(fd, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
91	  if (ret < 0)
92	    {
93	      printf("[LED] ERROR: set output: %d\n", errno);
94	      close(fd);
95	      return -errno;
96	    }
97	
98	  /* Step 4: 心跳灯循环 */
99	
100	  printf("[LED] Blinking at %d ms interval...\n", LED_BLINK_MS);
101	
102	  for (int i = 0; i < 20; i++)
103	    {
104	      state ^= 1;
105	      int value = LED_ACTIVE_HIGH ? state : !state;
106	      ioctl(fd, GPIOC_WRITE, value);
107	      up_mdelay(LED_BLINK_MS);
108	    }
109	
110	  /* Step 5: 关闭 */
111	
112	  ioctl(fd, GPIOC_WRITE, LED_ACTIVE_HIGH ? 0 : 1);  /* 熄灭 */
113	  close(fd);
114	
115	  printf("[LED] Done.\n");
116	  return 0;
117	}
