1	/****************************************************************************
2	 * assets/gpio_buzzer_template.c
3	 *
4	 * GPIO 蜂鸣器驱动模板（无源蜂鸣器，GPIO 方波驱动）
5	 *
6	 * Hummingbird 2K300 板蜂鸣器引脚：
7	 *   - BUZZER: GPIO75 (GPIO 输出)
8	 *
9	 * 使用说明：
10	 *   1. 引脚复用在 ls2k300_bringup.c 中已配置
11	 *   2. 无源蜂鸣器需要 GPIO 翻转产生方波，频率决定音调
12	 ****************************************************************************/
13	
14	#include <nuttx/config.h>
15	#include <sys/ioctl.h>
16	#include <stdio.h>
17	#include <fcntl.h>
18	#include <unistd.h>
19	#include <stdint.h>
20	
21	#include <nuttx/arch.h>
22	#include <nuttx/ioexpander/gpio.h>
23	
24	/* 已配置为 Hummingbird 2K300 板实际值 */
25	
26	#define BUZZER_PIN          75              /* 蜂鸣器 GPIO 引脚 */
27	
28	/* 音调参数 */
29	
30	#define TONE_1KHZ_HALF_US   500             /* 1kHz 半周期 500us */
31	#define TONE_2KHZ_HALF_US   250             /* 2kHz 半周期 250us */
32	#define TONE_500HZ_HALF_US  1000            /* 500Hz 半周期 1000us */
33	
34	/* 默认音调 */
35	
36	#define DEFAULT_HALF_CYCLE  TONE_1KHZ_HALF_US
37	
38	/* pinctrl 设置函数（需在板级代码中实现） */
39	
40	extern int pinctrl_set_gpio_function(int pin);
41	
42	static int g_buzzer_fd = -1;
43	
44	/****************************************************************************
45	 * Name: buzzer_init
46	 *
47	 * Description:
48	 *   初始化蜂鸣器 GPIO。
49	 *
50	 * Returned Value:
51	 *   0 on success, negative errno on failure.
52	 ****************************************************************************/
53	
54	int buzzer_init(void)
55	{
56	  int ret;
57	  char path[32];
58	
59	  ret = pinctrl_set_gpio_function(BUZZER_PIN);
60	  if (ret < 0)
61	    {
62	      printf("[BUZZER] ERROR: pinctrl failed for GPIO%d\n", BUZZER_PIN);
63	      return ret;
64	    }
65	
66	  snprintf(path, sizeof(path), "/dev/gpio%d", BUZZER_PIN);
67	  g_buzzer_fd = open(path, O_RDWR);
68	  if (g_buzzer_fd < 0)
69	    {
70	      printf("[BUZZER] ERROR: open %s: %d\n", path, errno);
71	      return -errno;
72	    }
73	
74	  ret = ioctl(g_buzzer_fd, GPIOC_SETPINTYPE,
75	              (unsigned long)GPIO_OUTPUT_PIN);
76	  if (ret < 0)
77	    {
78	      printf("[BUZZER] ERROR: set output: %d\n", errno);
79	      close(g_buzzer_fd);
80	      g_buzzer_fd = -1;
81	      return -errno;
82	    }
83	
84	  /* Buzzer off */
85	
86	  ioctl(g_buzzer_fd, GPIOC_WRITE, 0);
87	
88	  printf("[BUZZER] init done, GPIO%d\n", BUZZER_PIN);
89	  return 0;
90	}
