92	/****************************************************************************
93	 * Name: buzzer_beep
94	 *
95	 * Description:
96	 *   蜂鸣指定时长（默认 1kHz）。
97	 *
98	 * Parameters:
99	 *   duration_ms - 蜂鸣持续时间（毫秒）
100	 *   half_cycle  - 方波半周期（微秒），决定音调
101	 *                 TONE_1KHZ_HALF_US = 1kHz
102	 *                 TONE_2KHZ_HALF_US = 2kHz
103	 *                 TONE_500HZ_HALF_US = 500Hz
104	 ****************************************************************************/
105	
106	void buzzer_beep(unsigned int duration_ms, unsigned int half_cycle)
107	{
108	  unsigned int loops;
109	  unsigned int i;
110	
111	  if (g_buzzer_fd < 0)
112	    {
113	      return;
114	    }
115	
116	  if (half_cycle == 0)
117	    {
118	      half_cycle = DEFAULT_HALF_CYCLE;
119	    }
120	
121	  loops = (duration_ms * 1000u) / (half_cycle * 2u);
122	
123	  for (i = 0; i < loops; i++)
124	    {
125	      ioctl(g_buzzer_fd, GPIOC_WRITE, 1);
126	      up_udelay(half_cycle);
127	
128	      ioctl(g_buzzer_fd, GPIOC_WRITE, 0);
129	      up_udelay(half_cycle);
130	    }
131	
132	  /* Ensure buzzer off */
133	
134	  ioctl(g_buzzer_fd, GPIOC_WRITE, 0);
135	}
136	
137	/****************************************************************************
138	 * Name: buzzer_beep_simple
139	 *
140	 * Description:
141	 *   蜂鸣指定时长（默认 1kHz）。
142	 ****************************************************************************/
143	
144	void buzzer_beep_simple(unsigned int duration_ms)
145	{
146	  buzzer_beep(duration_ms, DEFAULT_HALF_CYCLE);
147	}
