149	/****************************************************************************
150	 * Name: buzzer_tone
151	 *
152	 * Description:
153	 *   持续输出指定频率的 tone，直到调用 buzzer_stop。
154	 *
155	 * Parameters:
156	 *   half_cycle - 方波半周期（微秒）
157	 ****************************************************************************/
158	
159	void buzzer_tone(unsigned int half_cycle)
160	{
161	  if (g_buzzer_fd < 0)
162	    {
163	      return;
164	    }
165	
166	  ioctl(g_buzzer_fd, GPIOC_WRITE, 1);
167	  up_udelay(half_cycle);
168	  ioctl(g_buzzer_fd, GPIOC_WRITE, 0);
169	  up_udelay(half_cycle);
170	}
171	
172	/****************************************************************************
173	 * Name: buzzer_stop
174	 *
175	 * Description:
176	 *   停止蜂鸣。
177	 ****************************************************************************/
178	
179	void buzzer_stop(void)
180	{
181	  if (g_buzzer_fd >= 0)
182	    {
183	      ioctl(g_buzzer_fd, GPIOC_WRITE, 0);
184	    }
185	}
186	
187	/****************************************************************************
188	 * Name: buzzer_deinit
189	 ****************************************************************************/
190	
191	void buzzer_deinit(void)
192	{
193	  if (g_buzzer_fd >= 0)
194	    {
195	      ioctl(g_buzzer_fd, GPIOC_WRITE, 0);
196	      close(g_buzzer_fd);
197	      g_buzzer_fd = -1;
198	    }
199	}
